#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;
    string t;
    cin >> t;

    vector<int> need(26, 0);
    for (char ch : t) need[ch - 'a']++;
    int missing = t.size(), bestL = 0, bestLen = s.size() + 1, l = 0;
    for (int rr = 0; rr < (int) s.size(); rr++) {
        int c = s[rr] - 'a';
        if (need[c] > 0) missing--;
        need[c]--;
        while (missing == 0) {
            if (rr - l + 1 < bestLen) {
                bestLen = rr - l + 1;
                bestL = l;
            }
            int d = s[l] - 'a';
            need[d]++;
            if (need[d] > 0) missing++;
            l++;
        }
    }
    if (bestLen > (int) s.size()) cout << -1 << "\n";
    else cout << s.substr(bestL, bestLen) << "\n";

    return 0;
}

